INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年正月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3cc54766-b2d2-5569-8a08-e7220a70b625"}, {"title": "朱棣开始举行午朝", "description": "朱棣开始举行午朝，让群臣奏事时可以从容陈说和议论。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年正月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0618cb66-9357-53f4-89de-f6405e36e6e6"}, {"title": "明廷举行祭孔典礼", "description": "三月初一，朝廷举行释奠礼祭祀孔子。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年三月辛卯朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "04780c0e-4e09-5c80-8d2f-940e37f8dcd4"}, {"title": "明廷在开原广宁设马市", "description": "朝廷在辽东开原、广宁设立马市。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年三月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ed592296-7e6e-586f-9099-d3d8b2dfbb3d"}, {"title": "明廷赐林环等进士及第或出身", "description": "朝廷分别赐林环等人进士及第或出身。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年三月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "77c5abe8-9e57-51eb-9e05-26281df932bb"}, {"title": "胡𡗨在芹站袭杀陈天平", "description": "胡𡗨在芹站袭杀陈天平，前大理卿薛嵓在此事中身亡。黄中等人率部返回。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年三月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d854ecb6-0d32-5ee9-b0fa-7fc3f690ef39"}, {"title": "明廷派使者访购遗书", "description": "朝廷派遣使者访购流传的旧书。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年四月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5675c7d4-2911-58ae-9e54-92baeaba43ba"}, {"title": "明廷赈济常州庐州安庆饥荒", "description": "朝廷下令赈济常州、庐州和安庆的饥荒。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年五月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "860283c8-6d8c-51bf-92ac-914c73ada927"}, {"title": "齐王朱榑被削官属护卫并留京", "description": "齐王朱榑获罪，朝廷削去他的属官和护卫，将他留在京师。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年五月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ce40b906-c92b-5fb2-9a0f-4a2ac942ac83"}, {"title": "本纪记日食预期及阴云遮挡", "description": "六月初一预期有日食，阴云遮蔽，未能看见。礼官请求上表庆贺，朱棣没有准许。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年六月己未朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2357bdac-22cd-5be6-b8d1-ab219e748f41"}, {"title": "南阳献瑞麦，朱棣命进献宗庙", "description": "南阳献上称为祥瑞的麦穗。朱棣对礼部说，近来郡县屡报祥瑞，唯有这份麦子是丰年的征兆，于是命将它供于宗庙。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年六月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "74053355-dc3b-5f56-a7bb-25972dfd19d9"}, {"title": "明廷命朱能沐晟张辅分路征安南", "description": "朝廷命朱能为征夷将军，沐晟、张辅为副将，率军分头进攻安南。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年七月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1bef0acd-f6cf-585b-91f7-dbe4b1f718e7"}, {"title": "刘儁参赞交南军务", "description": "永乐4年（年号对照1406年）七月，刘儁参赞交南军务。", "start_year": 1406, "end_year": 1406, "time_original": "永乐4年（年号对照1406年）七月；公元年核为1406年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "9e927d59-8e87-57f4-b704-79e4e88f1a18"}, {"title": "黄福陈洽督办征安南的粮饷", "description": "行部尚书黄福与大理卿陈洽奉命督办征安南军队的粮饷。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年七月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "770da09a-6734-5d4b-ba09-448a75c0e7a6"}, {"title": "征安南诏令规定不得掠民或杀降", "description": "朱棣在征安南的诏令中，要求不纵容变乱，不轻忽敌军，不得毁坏民居坟墓、践踏庄稼、抢掠财物人口或杀害归降者，违者即使有功也不赦。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d370863e-385a-553f-ada1-9e9b7d08f6e5"}, {"title": "明廷重申诽谤禁令", "description": "朝廷再次申明禁止诽谤的规定。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年七月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ab5c63d2-4014-5a3d-8f6a-c4144669aea3"}, {"title": "明廷下诏建北京宫殿并分派大臣采木", "description": "朝廷计划次年五月建造北京宫殿，分派大臣赴四川、湖广、江西、浙江和山西采办木料。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年闰七月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4f9e92b1-e7e5-524c-af76-e6ee1a0eaedb"}, {"title": "明廷命通政司上报涉及民事的奏书", "description": "朝廷命通政司，凡上书涉及民事的，即使事情很小也要上报。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年八月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8deb5fb3-4d59-58c7-8ea4-445b26dee848"}, {"title": "齐王朱榑被废为庶人", "description": "朝廷在八月癸丑废齐王朱榑为庶人。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年八月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8c43d576-a64b-5740-b3e6-11948550bbc3"}, {"title": "明廷赈济六地返回恢复生计的流民", "description": "朝廷救济苏、松、常、杭、嘉、湖返乡恢复生计的流民。本纪记涉及十二万余户。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年九月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "347c6611-ad5e-5cbb-a1a4-7bd4af6872f4"}, {"title": "朱能在军中去世，张辅接掌其部", "description": "成国公朱能在军中去世，张辅接掌其部。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年十月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8fbacb50-d50a-593b-8ade-a5015b40e940"}, {"title": "明军攻下隘留关", "description": "本纪记载，明军于十月乙未攻下隘留关。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年十月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "961e75e8-45be-5bc2-8137-2e04a9ebf984"}, {"title": "沐晟率部在白鹤会师", "description": "沐晟率军在白鹤与其他部队会师。", "start_year": 1406, "end_year": 1406, "time_original": "永乐四年十月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cfd6f29f-4442-5ded-8004-f670613c217c"}, {"title": "明廷把本纪所称甘露醴泉供于太庙", "description": "本纪记孝陵松柏出现甘露，神乐观涌出醴泉。朝廷把它们进献于太庙，并赏赐百官。", "start_year": 1407, "end_year": 1407, "time_original": "永乐四年十一月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dea085d6-8b90-512d-95be-9624b637d515"}, {"title": "明廷赦免殊死以下罪犯", "description": "朝廷下令赦免本纪所称殊死以下的罪犯。", "start_year": 1407, "end_year": 1407, "time_original": "永乐四年十二月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9794f654-5916-5a02-93b2-f1a05828e031"}, {"title": "张辅在嘉林江击败安南军", "description": "张辅率军在嘉林江大败安南军。", "start_year": 1407, "end_year": 1407, "time_original": "永乐四年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "260e4315-ce02-5815-b516-9605b1335e5c"}, {"title": "明军攻下多邦城", "description": "本纪记载，明军在十二月丙申攻下多邦城。", "start_year": 1407, "end_year": 1407, "time_original": "永乐四年十二月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a884717b-e639-5480-ba4c-23d6bcc85a78"}, {"title": "明军攻占安南东都", "description": "本纪记载，明军于丁酉攻占安南东都。", "start_year": 1407, "end_year": 1407, "time_original": "永乐四年十二月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "525b2ed8-9b12-5401-81e7-05f927160a10"}, {"title": "明军攻占安南西都", "description": "本纪记载，明军于癸卯攻占安南西都，对方逃向海上。", "start_year": 1407, "end_year": 1407, "time_original": "永乐四年十二月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "36b82054-6ee1-5108-a932-13d85b1f3ee5"}, {"title": "瓯宁王邸第起火后去世", "description": "本纪载瓯宁王允𤐤的邸第在辛亥起火，瓯宁王去世。", "start_year": 1407, "end_year": 1407, "time_original": "永乐四年十二月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c5401b2e-1b6a-578d-8f7d-5294cf8deefd"}, {"title": "暹罗等地遣使入贡", "description": "本纪记暹罗、占城、于阗、浡泥、日本、琉球中山及山南、婆罗入贡，另记爪哇东、西王及真腊入贡两次，别失八里来贡三次。 按原历纪年，事情发生在公元1406至1407年之间。", "start_year": null, "end_year": null, "time_original": "永乐四年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ad60e52d-c916-53e6-b129-8f1ccbafd0e0"}, {"title": "明廷退回琉球进献人员并谢绝结牙曲献玉碗", "description": "琉球进献宦者，明廷将他们送还。回回结牙曲进献玉碗，明廷也退回贡品。 按原历纪年，事情发生在公元1406至1407年之间。", "start_year": null, "end_year": null, "time_original": "永乐四年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "713373ca-e576-5318-a9bc-bd80ee7e84b9"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

